insert into public.registry_settings (id, registry_title, welcome_heading, welcome_text, prices_recorded_on, price_notice, doc_budget_total_aed, doc_full_total_aed, doc_totals_note)
values (1, 'Our Baby Registry', 'Made with love for our little one.', 'We’ve put together a little wishlist of things we’re excited to welcome our baby with. If you’d like to contribute, choose something you love from the list. Thank you for being part of this special journey.', '2026-10-24', 'Prices were recorded in Dubai on 24 October 2026 and may have changed. Please double-check the price with the retailer before buying.', 7860, 25500, 'Budget uses the cheaper option for each need, e.g. the Doona+ as car seat and stroller in one, the bedside cot bought online, and sale prices on clothes. Full wishlist takes the premium picks in each section plus every extra from the inspiration pictures. Estimates use the middle of each range. Not counted in either total, because they are alternatives to items already included: Bugaboo stroller, Cybex Sirona T, Bugaboo travel cot, BabyBjörn bouncer, Luma bath, and the Strips cot, Kenva and Pluto dressers.')
on conflict (id) do nothing;

